// Move everyone who deploys onto team 2.
const TARGET_TEAM = 2;

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    if (!mod.IsPlayerValid(eventPlayer)) return;

    const target = mod.GetTeam(TARGET_TEAM);

    // Already there. Calling SetTeam again would respawn them for nothing.
    if (mod.Equals(mod.GetTeam(eventPlayer), target)) return;

    mod.SetTeam(eventPlayer, target);
}

let aliveCount = 0;

export function OnGameModeStarted(): void {
    const players = mod.AllPlayers(); // a mod.Array, not a JavaScript array
    const count = mod.CountOf(players); // ask the engine how long it is

    aliveCount = 0;

    for (let i = 0; i < count; i++) {
        const player = mod.ValueInArray(players, i) as mod.Player;

        // A player can leave mid loop, which leaves a handle pointing at nothing.
        if (!mod.IsPlayerValid(player)) continue;

        if (mod.GetSoldierState(player, mod.SoldierStateBool.IsAlive)) aliveCount++;
    }

    console.log(`Alive players: ${aliveCount}`);
}

function countTeam(team: mod.Team): number {
    const players = mod.AllPlayers();
    const count = mod.CountOf(players);
    let total = 0;

    for (let i = 0; i < count; i++) {
        const player = mod.ValueInArray(players, i) as mod.Player;
        if (!mod.IsPlayerValid(player)) continue;
        if (mod.Equals(mod.GetTeam(player), team)) total++;
    }

    return total;
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    if (!mod.IsPlayerValid(eventPlayer)) return;

    const teamOne = mod.GetTeam(1);
    const teamTwo = mod.GetTeam(2);
    const oneCount = countTeam(teamOne);
    const twoCount = countTeam(teamTwo);

    // Slack of one, otherwise two players deploying together bounce back and forth.
    if (oneCount > twoCount + 1) mod.SetTeam(eventPlayer, teamTwo);
    if (twoCount > oneCount + 1) mod.SetTeam(eventPlayer, teamOne);
}

const SPAWN_POINT_ID = 1001; // the ObjId you gave the SpawnPoint node in Godot

export async function OnPlayerDied(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDeathType: mod.DeathType,
    eventWeaponUnlock: mod.WeaponUnlock
): Promise<void> {
    // Let the death finish before putting them back in.
    await mod.Wait(0.5);

    // They may have left the server during that half second.
    if (!mod.IsPlayerValid(eventPlayer)) return;

    mod.SpawnPlayerFromSpawnPoint(eventPlayer, mod.GetSpawnPoint(SPAWN_POINT_ID));
}

const FIRST_SPAWN_POINT_ID = 1001;
const SPAWN_POINT_COUNT = 5; // ObjIds 1001 to 1005

let nextSpawn = 0;

export async function OnPlayerDied(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDeathType: mod.DeathType,
    eventWeaponUnlock: mod.WeaponUnlock
): Promise<void> {
    // Step to the next point and wrap back round at the end of the list.
    nextSpawn = (nextSpawn + 1) % SPAWN_POINT_COUNT;

    await mod.Wait(0.5);
    if (!mod.IsPlayerValid(eventPlayer)) return;

    mod.SpawnPlayerFromSpawnPoint(eventPlayer, mod.GetSpawnPoint(FIRST_SPAWN_POINT_ID + nextSpawn));
}

const SPAWN_POINT_ID = 1001;

export async function OnGameModeStarted(): Promise<void> {
    // A mod that disabled deploying earlier would swallow every deploy request.
    mod.EnableAllPlayerDeploy(true);

    // Three passes, a second apart, catches players who were still loading.
    for (let attempt = 0; attempt < 3; attempt++) {
        await mod.Wait(1);

        const players = mod.AllPlayers();
        const count = mod.CountOf(players);

        for (let i = 0; i < count; i++) {
            const player = mod.ValueInArray(players, i) as mod.Player;
            if (!mod.IsPlayerValid(player)) continue;
            if (mod.GetSoldierState(player, mod.SoldierStateBool.IsAlive)) continue;

            // Direct placement, which does not depend on the deploy screen.
            mod.SpawnPlayerFromSpawnPoint(player, mod.GetSpawnPoint(SPAWN_POINT_ID));
        }
    }
}

const SCORE_ZONE_ID = 201; // the ObjId on the AreaTrigger node in Godot

export function OnPlayerEnterAreaTrigger(eventPlayer: mod.Player, eventAreaTrigger: mod.AreaTrigger): void {
    // Every AreaTrigger raises this same event, so check which one fired.
    if (mod.GetObjId(eventAreaTrigger) !== SCORE_ZONE_ID) return;

    const team = mod.GetTeam(eventPlayer);
    mod.SetGameModeScore(team, mod.GetGameModeScore(team) + 1);
}

export function OnPlayerExitAreaTrigger(eventPlayer: mod.Player, eventAreaTrigger: mod.AreaTrigger): void {
    if (mod.GetObjId(eventAreaTrigger) !== SCORE_ZONE_ID) return;

    console.log(`Player ${mod.GetObjId(eventPlayer)} left the score zone.`);
}

const TEAM_ONE_BASE_TRIGGER = 201;
const BASE_OWNER_TEAM = 1;
const GRACE_SECONDS = 3;

export async function OnPlayerEnterAreaTrigger(
    eventPlayer: mod.Player,
    eventAreaTrigger: mod.AreaTrigger
): Promise<void> {
    if (mod.GetObjId(eventAreaTrigger) !== TEAM_ONE_BASE_TRIGGER) return;

    // Players who own this base are allowed in.
    if (mod.Equals(mod.GetTeam(eventPlayer), mod.GetTeam(BASE_OWNER_TEAM))) return;

    await mod.Wait(GRACE_SECONDS);

    if (!mod.IsPlayerValid(eventPlayer)) return;
    if (!mod.GetSoldierState(eventPlayer, mod.SoldierStateBool.IsAlive)) return;

    mod.Kill(eventPlayer);
}

const PLAY_AREA_TRIGGER = 300; // your own boundary, an AreaTrigger in Godot
const CENTRE_MARKER = 500; // a real prop, because spawners report position 0,0,0

export function OnPlayerExitAreaTrigger(eventPlayer: mod.Player, eventAreaTrigger: mod.AreaTrigger): void {
    if (mod.GetObjId(eventAreaTrigger) !== PLAY_AREA_TRIGGER) return;
    if (!mod.IsPlayerValid(eventPlayer)) return;

    const centre = mod.GetObjectPosition(mod.GetSpatialObject(CENTRE_MARKER));

    // Third argument is the facing angle in degrees.
    mod.Teleport(eventPlayer, centre, 0);
}

const CAPTURING_SECONDS = 15; // taking a neutral flag
const NEUTRALISE_SECONDS = 10; // stripping a flag off the other team

export function OnGameModeStarted(): void {
    const points = mod.AllCapturePoints();
    const count = mod.CountOf(points);

    for (let i = 0; i < count; i++) {
        const point = mod.ValueInArray(points, i) as mod.CapturePoint;

        // Enable first. A disabled point ignores the timer calls.
        mod.EnableGameModeObjective(point, true);

        mod.SetCapturePointCapturingTime(point, CAPTURING_SECONDS);
        mod.SetCapturePointNeutralizationTime(point, NEUTRALISE_SECONDS);

        // How much faster a full squad captures than one player.
        mod.SetMaxCaptureMultiplier(point, 2);
    }
}

const FLAG_A = 201; // the ObjId on the CapturePoint node in Godot

export function OnGameModeStarted(): void {
    const flagA = mod.GetCapturePoint(FLAG_A);

    // Enable first. Setting the owner of a disabled point does nothing.
    mod.EnableGameModeObjective(flagA, true);
    mod.SetCapturePointOwner(flagA, mod.GetTeam(1));

    // The getter is GetCurrentOwnerTeam, there is no GetCapturePointOwner.
    console.log(`Flag A owner team id: ${mod.GetObjId(mod.GetCurrentOwnerTeam(flagA))}`);
}

const CAPTURE_BONUS = 100;

export function OnCapturePointCaptured(eventCapturePoint: mod.CapturePoint): void {
    // Who owns it now that the capture finished.
    const owner = mod.GetCurrentOwnerTeam(eventCapturePoint);

    mod.SetGameModeScore(owner, mod.GetGameModeScore(owner) + CAPTURE_BONUS);

    console.log(`Point ${mod.GetObjId(eventCapturePoint)} taken by team ${mod.GetObjId(owner)}.`);
}

const LOW_HEALTH = 25;

// OngoingPlayer is called over and over, so remember the previous answer per player
// to get the once per change behaviour a block Ongoing rule gives you for free.
const wasLow = new Map<number, boolean>();

export function OngoingPlayer(eventPlayer: mod.Player): void {
    if (!mod.IsPlayerValid(eventPlayer)) return;

    const id = mod.GetObjId(eventPlayer);
    const health = mod.GetSoldierState(eventPlayer, mod.SoldierStateNumber.CurrentHealth);
    const isLow = health < LOW_HEALTH;

    // Only act on the change from not low to low.
    if (isLow && !wasLow.get(id)) mod.Heal(eventPlayer, 100);

    wasLow.set(id, isLow);
}

export async function OnPlayerEarnedKill(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDeathType: mod.DeathType,
    eventWeaponUnlock: mod.WeaponUnlock
): Promise<void> {
    // await is what actually pauses. Without it the wait does nothing at all.
    await mod.Wait(2);

    // Two seconds passed, so nothing about the player can be assumed any more.
    if (!mod.IsPlayerValid(eventPlayer)) return;
    if (!mod.GetSoldierState(eventPlayer, mod.SoldierStateBool.IsAlive)) return;

    mod.Heal(eventPlayer, 50);
}

const HEADSHOT_BONUS = 50;

// Keyed by player id, never by the player object itself.
const hitsTaken = new Map<number, number>();

// Synchronous on purpose. Making this async is what leaks and kills the script.
export function OnPlayerDamaged(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDamageType: mod.DamageType,
    eventWeaponUnlock: mod.WeaponUnlock
): void {
    const id = mod.GetObjId(eventPlayer);
    hitsTaken.set(id, (hitsTaken.get(id) ?? 0) + 1);
}

export function OnPlayerDied(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDeathType: mod.DeathType,
    eventWeaponUnlock: mod.WeaponUnlock
): void {
    hitsTaken.delete(mod.GetObjId(eventPlayer));

    // The death type is an opaque handle, so it needs this compare, not ===.
    if (!mod.EventDeathTypeCompare(eventDeathType, mod.PlayerDeathTypes.Headshot)) return;
    if (!mod.IsPlayerValid(eventOtherPlayer)) return;

    const killerTeam = mod.GetTeam(eventOtherPlayer);
    mod.SetGameModeScore(killerTeam, mod.GetGameModeScore(killerTeam) + HEADSHOT_BONUS);
}
